import React from 'react';

import { selectArticleAsync } from '@apps/Articles/components/ArticleSelectModal';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import { getHikingDataAsync } from '../@services/hiking.service';
import {
  addHikingArticle,
  deleteHikingArticle,
  editHikingArticle,
  getHikingArticles,
} from '../@services/hikingArticles.service';
import { getHikingAccessGroupAsync } from '../@services/hikingRules.service';
import { HikingAccessGroup } from '../@types/hiking.rules';
import { IHikingData } from '../@types/hiking.types';
import { editHikingArticleInModal } from './components/HikingArticleForm';
import {
  getEmptyHikingArticle,
  mapHikingArticleToAdd,
  mapHikingArticleToUpdate,
} from '../@mappers/hikingArticles.mapper';
import { IHikingArticle } from '../@types/hikingArticles.types';
import HikingArticleListItem from './components/HikingArticleListItem';

interface IHikingArticlesPageProps {
  id_hiking: number;
}

const HikingArticlesPage: React.FC<IHikingArticlesPageProps> = ({ id_hiking }) => {
  const [data, setData] = React.useState<IHikingArticle[]>([]);
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setIsErr] = React.useState<Error>();
  const [canEdit, setCanEdit] = React.useState(false);

  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const ha = await getHikingArticles(id_hiking);
        setData(ha);

        const accessGroup = await getHikingAccessGroupAsync(id_hiking);
        setCanEdit(
          [
            HikingAccessGroup.Full,
            HikingAccessGroup.All,
            HikingAccessGroup.Boss,
            HikingAccessGroup.Info,
          ].includes(accessGroup),
        );
      } catch (error) {
        setIsErr(err as Error);
        console.error(error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData) {
    return null;
  }

  const handleAdd = async () => {
    if (!authContext.user) return;
    const article = await selectArticleAsync({ filter: {} });
    const newHikingArticle = await editHikingArticleInModal(
      getEmptyHikingArticle({ author: authContext.user, article }),
    );
    const id = await addHikingArticle(mapHikingArticleToAdd(id_hiking, newHikingArticle));
    setData((cur) => [...cur, { ...newHikingArticle, id }]);
    notificationHelper.success('Статья добавлена в поход');
  };

  const handleEdit = async (hikingArticle: IHikingArticle) => {
    const updatedHikingArticle = await editHikingArticleInModal(hikingArticle);
    await editHikingArticle(mapHikingArticleToUpdate(id_hiking, updatedHikingArticle));
    setData((cur) => cur.map((x) => (x.id === updatedHikingArticle.id ? updatedHikingArticle : x)));
    notificationHelper.success('Сохранено');
  };

  const handleDelete = async (hikingArticle: IHikingArticle) => {
    const ok = await confirmModal2(`Удалить "${hikingArticle.article.name}" из похода?`);
    if (!ok) return;

    await deleteHikingArticle({ id: hikingArticle.id, id_hiking });
    setData((cur) => cur.filter((x) => x.id !== hikingArticle.id));
    notificationHelper.success('Сохранено');
  };

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          {
            href: `/hiking/${id_hiking}/articles`,
            text: 'Статьи',
            active: true,
          },
        ]}
      />
      <PageHeader title={`Статьи похода «${hikingData.name}»`}>
        {canEdit && (
          <>
            <PohButton variant={ButtonVariant.Success} onClick={handleAdd}>
              Добавить
            </PohButton>
          </>
        )}
      </PageHeader>
      <section>
        {!data.length && <Empty>Нет статей связанных с походом</Empty>}
        {!!data.length && (
          <PohList
            data={data.map((x) => {
              return {
                key: x.id,
                children: (
                  <HikingArticleListItem
                    id_hiking={id_hiking}
                    hikingArticle={x}
                    toolbar={
                      canEdit ? (
                        <>
                          <PohButton
                            icon={IconsEnum.trash}
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDelete(x);
                            }}
                            size={ButtonSize.Small}
                          />
                          <PohButton
                            icon={IconsEnum.edit}
                            size={ButtonSize.Small}
                            onClick={(e) => {
                              e.stopPropagation();
                              handleEdit(x);
                            }}
                          />
                        </>
                      ) : null
                    }
                  />
                ),
              };
            })}
          />
        )}
      </section>
    </PohContainer>
  );
};

export default HikingArticlesPage;
