import React from 'react';

import { Link } from 'react-router-dom';

import { IHikingArticle } from '@apps/Hiking/@types/hikingArticles.types';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IHikingArticleListItemProps {
  hikingArticle: IHikingArticle;
  toolbar: React.ReactNode;
  id_hiking: number;
}

const HikingArticleListItem = ({
  id_hiking,
  hikingArticle,
  toolbar,
}: IHikingArticleListItemProps) => {
  return (
    <PohRow>
      <PohCol sm={4}>
        <Link to={`/hiking/${id_hiking}/articles/${hikingArticle.id}`}>
          {hikingArticle.article.name}
        </Link>
      </PohCol>
      <PohCol sm={4}>
        <em className="text-truncate text-ellipsis">
          <small>{hikingArticle.comment}</small>
        </em>
      </PohCol>
      <PohCol sm={4} className="d-flex">
        {hikingArticle.actual_in && <small>{hikingArticle.actual_in.toLocaleString()}</small>}
        {hikingArticle.actual_out && (
          <small className="ms-2 me-3">{hikingArticle.actual_out.toLocaleString()}</small>
        )}
        {toolbar && (
          <aside
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
            }}
            className="ms-auto d-flex"
            style={{ gap: 6 }}
          >
            {toolbar}
          </aside>
        )}
      </PohCol>
    </PohRow>
  );
};

export default HikingArticleListItem;
